    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    await ui.loadSheet(pg_uma, sheet);
    expect(await ui.exportTree(pg_uma)).toBe(`sheet,name,grade,due-total
${sheet},Ada,A,2.00
${sheet},Ben,B,n/a
${sheet}-c1,Cy,A,1.00
${sheet}-c1,Di,B,4.00
`);
